CREATE TABLE public.schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),work_id uuid UNIQUE REFERENCES public.work_registry(id),budget_id uuid REFERENCES public.budgets(id),client_id uuid REFERENCES public.people(id),client_name text NOT NULL DEFAULT '',name text NOT NULL,address text,description text,planned_start date,planned_end date,responsible text,notes text,is_template boolean NOT NULL DEFAULT false,archived boolean NOT NULL DEFAULT false,standalone_stages jsonb NOT NULL DEFAULT '[]',created_by uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(planned_end IS NULL OR planned_start IS NULL OR planned_end>=planned_start),CHECK(jsonb_typeof(standalone_stages)='array'));
GRANT SELECT,INSERT,UPDATE ON public.schedules TO authenticated; GRANT ALL ON public.schedules TO service_role;
ALTER TABLE public.schedules ENABLE ROW LEVEL SECURITY;
CREATE POLICY schedules_read ON public.schedules FOR SELECT TO authenticated USING(public.can_see_costs(auth.uid()) OR public.has_role(auth.uid(),'equipe'));
CREATE POLICY schedules_write ON public.schedules FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE TABLE public.schedule_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),schedule_id uuid NOT NULL REFERENCES public.schedules(id),version integer NOT NULL,stages jsonb NOT NULL,notes text,reason text NOT NULL,created_by uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(schedule_id,version));
GRANT SELECT ON public.schedule_versions TO authenticated;GRANT ALL ON public.schedule_versions TO service_role;
ALTER TABLE public.schedule_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY independent_versions_read ON public.schedule_versions FOR SELECT TO authenticated USING(public.can_see_costs(auth.uid()) OR public.has_role(auth.uid(),'equipe'));
CREATE TRIGGER standalone_version_immutable BEFORE UPDATE OR DELETE ON public.schedule_versions FOR EACH ROW EXECUTE FUNCTION public.guard_schedule_version_immutable();
INSERT INTO public.schedules(work_id,budget_id,client_id,client_name,name,address,planned_start,planned_end,responsible,notes,archived) SELECT w.id,w.linked_budget_id,w.client_id,coalesce(p.name,''),w.name,w.address,w.planned_start,w.planned_end,w.responsible,w.schedule_notes,w.archived FROM public.work_registry w LEFT JOIN public.people p ON p.id=w.client_id;
CREATE FUNCTION public.ensure_work_schedule() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.schedules(work_id,budget_id,client_id,client_name,name,address,planned_start,planned_end,responsible,notes,archived) VALUES(new.id,new.linked_budget_id,new.client_id,coalesce((SELECT name FROM public.people WHERE id=new.client_id),''),new.name,new.address,new.planned_start,new.planned_end,new.responsible,new.schedule_notes,new.archived) ON CONFLICT(work_id) DO UPDATE SET name=excluded.name,address=excluded.address,client_id=excluded.client_id,client_name=excluded.client_name,archived=excluded.archived; RETURN new; END $$;
CREATE TRIGGER work_schedule_header AFTER INSERT OR UPDATE ON public.work_registry FOR EACH ROW EXECUTE FUNCTION public.ensure_work_schedule();
CREATE FUNCTION public.validate_standalone_stages(_stages jsonb) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE s jsonb; n integer; BEGIN IF jsonb_typeof(_stages)<>'array' OR jsonb_array_length(_stages)>500 THEN RAISE EXCEPTION 'Etapas inválidas.'; END IF; SELECT count(DISTINCT x->>'id') INTO n FROM jsonb_array_elements(_stages) x; IF n<>jsonb_array_length(_stages) THEN RAISE EXCEPTION 'Identificadores de etapas inválidos.'; END IF; FOR s IN SELECT value FROM jsonb_array_elements(_stages) LOOP PERFORM (s->>'id')::uuid; IF nullif(trim(s->>'name'),'') IS NULL OR coalesce((s->>'progress')::numeric,0) NOT BETWEEN 0 AND 100 OR coalesce((s->>'weight')::numeric,0) NOT BETWEEN 0 AND 100 THEN RAISE EXCEPTION 'Confira nome e percentuais da etapa.'; END IF; IF nullif(s->>'planned_end','')::date<nullif(s->>'planned_start','')::date OR nullif(s->>'actual_end','')::date<nullif(s->>'actual_start','')::date THEN RAISE EXCEPTION 'Término anterior ao início.'; END IF; IF nullif(s->>'dependency_id','') IS NOT NULL THEN IF s->>'dependency_id'=s->>'id' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_stages) x WHERE x->>'id'=s->>'dependency_id') THEN RAISE EXCEPTION 'Dependência inválida.'; END IF; IF EXISTS(WITH RECURSIVE chain AS(SELECT x->>'id' id,x->>'dependency_id' dep FROM jsonb_array_elements(_stages) x WHERE x->>'id'=s->>'dependency_id' UNION SELECT x->>'id',x->>'dependency_id' FROM jsonb_array_elements(_stages) x JOIN chain c ON x->>'id'=c.dep) SELECT 1 FROM chain WHERE id=s->>'id') THEN RAISE EXCEPTION 'Dependência circular.'; END IF; END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.validate_standalone_stages(jsonb) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.guard_schedule_header() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (new.work_id IS DISTINCT FROM old.work_id OR new.standalone_stages IS DISTINCT FROM old.standalone_stages) AND coalesce(current_setting('jmg.schedule_operation',true),'')<>'on' THEN RAISE EXCEPTION 'Use a operação de edição ou vínculo do cronograma.'; END IF; IF TG_OP='INSERT' AND (new.work_id IS NOT NULL OR jsonb_array_length(new.standalone_stages)>0) AND coalesce(current_setting('jmg.schedule_operation',true),'')<>'on' AND pg_trigger_depth()<2 THEN RAISE EXCEPTION 'Use Novo Cronograma.'; END IF; new.updated_at:=now();RETURN new; END $$;
CREATE TRIGGER schedules_guard BEFORE INSERT OR UPDATE ON public.schedules FOR EACH ROW EXECUTE FUNCTION public.guard_schedule_header();
CREATE FUNCTION public.save_standalone_schedule(_id uuid,_stages jsonb,_notes text,_reason text,_approve boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h public.schedules; v integer; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO h FROM public.schedules WHERE id=_id FOR UPDATE; IF NOT FOUND OR h.work_id IS NOT NULL THEN RAISE EXCEPTION 'Abra o cronograma vinculado na obra.'; END IF; PERFORM public.validate_standalone_stages(_stages); SELECT coalesce(max(version),0) INTO v FROM public.schedule_versions WHERE schedule_id=_id; IF _approve AND v>0 THEN RAISE EXCEPTION 'Original já preservado.'; END IF; IF v>0 AND (h.standalone_stages IS DISTINCT FROM _stages OR h.notes IS DISTINCT FROM _notes) AND nullif(trim(_reason),'') IS NULL THEN RAISE EXCEPTION 'Informe o motivo da reprogramação.'; END IF; IF _approve AND (jsonb_array_length(_stages)=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_stages) x WHERE nullif(x->>'planned_start','') IS NULL OR nullif(x->>'planned_end','') IS NULL)) THEN RAISE EXCEPTION 'Defina datas para todas as etapas.'; END IF; PERFORM set_config('jmg.schedule_operation','on',true); UPDATE public.schedules SET standalone_stages=_stages,notes=_notes WHERE id=_id; IF _approve OR v>0 AND (h.standalone_stages IS DISTINCT FROM _stages OR h.notes IS DISTINCT FROM _notes) THEN INSERT INTO public.schedule_versions(schedule_id,version,stages,notes,reason) VALUES(_id,v+1,_stages,_notes,CASE WHEN _approve THEN 'Cronograma original aprovado' ELSE _reason END); END IF; END $$;
REVOKE ALL ON FUNCTION public.save_standalone_schedule(uuid,jsonb,text,text,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.save_standalone_schedule(uuid,jsonb,text,text,boolean) TO authenticated;
CREATE FUNCTION public.create_schedule(_data jsonb,_work_id uuid DEFAULT NULL,_budget_id uuid DEFAULT NULL,_copy_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; w public.work_registry; b public.budgets; src public.schedules; rows jsonb; mapping jsonb; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; PERFORM set_config('jmg.schedule_operation','on',true); IF _work_id IS NOT NULL THEN SELECT * INTO w FROM public.work_registry WHERE id=_work_id AND NOT archived FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Obra não encontrada.'; END IF; SELECT id INTO sid FROM public.schedules WHERE work_id=w.id; IF sid IS NULL THEN INSERT INTO public.schedules(work_id,name,client_id,client_name,address) VALUES(w.id,w.name,w.client_id,coalesce((SELECT name FROM public.people WHERE id=w.client_id),''),w.address) RETURNING id INTO sid; END IF; IF w.linked_budget_id IS NOT NULL THEN PERFORM public.import_work_schedule(w.id); END IF; RETURN sid; END IF;
IF _copy_id IS NOT NULL THEN SELECT * INTO src FROM public.schedules WHERE id=_copy_id; IF NOT FOUND THEN RAISE EXCEPTION 'Cronograma não encontrado.'; END IF; IF src.work_id IS NULL THEN rows:=src.standalone_stages; ELSE SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY sort),'[]') INTO rows FROM public.work_stages s WHERE work_id=src.work_id; END IF; SELECT coalesce(jsonb_object_agg(x->>'id',gen_random_uuid()::text),'{}') INTO mapping FROM jsonb_array_elements(rows) x; SELECT coalesce(jsonb_agg((x - 'work_id' - 'budget_section_id' - 'created_by' - 'updated_by' - 'created_at' - 'updated_at')||jsonb_build_object('id',mapping->>(x->>'id'),'dependency_id',mapping->>(x->>'dependency_id'),'progress',0,'status','nao_iniciado','actual_start',NULL,'actual_end',NULL)),'[]') INTO rows FROM jsonb_array_elements(rows) x;
ELSIF _budget_id IS NOT NULL THEN SELECT * INTO b FROM public.budgets WHERE id=_budget_id; IF NOT FOUND THEN RAISE EXCEPTION 'Orçamento não encontrado.'; END IF; SELECT coalesce(jsonb_agg(jsonb_build_object('id',gen_random_uuid(),'name',bs.title,'sort',bs.sort,'weight',0,'progress',0,'status','nao_iniciado','planned_start',NULL,'planned_end',NULL,'scope_services',(SELECT string_agg(bi.description,E'\n' ORDER BY bi.sort) FROM public.budget_items bi WHERE bi.section_id=bs.id)) ORDER BY bs.sort),'[]') INTO rows FROM public.budget_sections bs WHERE bs.budget_id=b.id;
ELSE rows:='[]'; END IF;
INSERT INTO public.schedules(budget_id,client_id,client_name,name,address,description,planned_start,planned_end,responsible,notes,standalone_stages) VALUES(_budget_id,coalesce(nullif(_data->>'client_id','')::uuid,b.client_id),coalesce(_data->>'client_name',b.client_display,src.client_name,''),coalesce(nullif(_data->>'name',''),b.title,src.name||' · cópia','Novo cronograma'),coalesce(_data->>'address',b.endereco,src.address),_data->>'description',nullif(_data->>'planned_start','')::date,nullif(_data->>'planned_end','')::date,_data->>'responsible',coalesce(_data->>'notes',src.notes),rows) RETURNING id INTO sid;RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.create_schedule(jsonb,uuid,uuid,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.create_schedule(jsonb,uuid,uuid,uuid) TO authenticated;
CREATE FUNCTION public.link_schedule_work(_schedule_id uuid,_work_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h public.schedules; target uuid; s jsonb; v record; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; PERFORM id FROM public.work_registry WHERE id=_work_id AND NOT archived FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Obra não encontrada.'; END IF; SELECT * INTO h FROM public.schedules WHERE id=_schedule_id FOR UPDATE; IF NOT FOUND OR h.work_id IS NOT NULL OR h.is_template THEN RAISE EXCEPTION 'Selecione um cronograma avulso, não um modelo.'; END IF; SELECT id INTO target FROM public.schedules WHERE work_id=_work_id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.work_stages WHERE work_id=_work_id) OR EXISTS(SELECT 1 FROM public.work_schedule_versions WHERE work_id=_work_id) THEN RAISE EXCEPTION 'Esta obra já possui etapas ou histórico. Escolha uma obra sem planejamento; nenhum registro foi substituído.'; END IF; PERFORM public.validate_standalone_stages(h.standalone_stages);PERFORM set_config('jmg.schedule_operation','on',true);PERFORM set_config('jmg.schedule_batch','on',true);
FOR s IN SELECT value FROM jsonb_array_elements(h.standalone_stages) LOOP INSERT INTO public.work_stages(id,work_id,name,sort,responsible,planned_start,planned_end,actual_start,actual_end,weight,progress,status,observations,scope_services,schedule_change_reason) VALUES((s->>'id')::uuid,_work_id,s->>'name',coalesce((s->>'sort')::integer,0),s->>'responsible',nullif(s->>'planned_start','')::date,nullif(s->>'planned_end','')::date,nullif(s->>'actual_start','')::date,nullif(s->>'actual_end','')::date,coalesce((s->>'weight')::numeric,0),coalesce((s->>'progress')::numeric,0),coalesce(s->>'status','nao_iniciado'),s->>'observations',s->>'scope_services','Vínculo de cronograma avulso'); END LOOP;
FOR s IN SELECT value FROM jsonb_array_elements(h.standalone_stages) LOOP UPDATE public.work_stages SET dependency_id=nullif(s->>'dependency_id','')::uuid WHERE id=(s->>'id')::uuid;END LOOP;
FOR v IN SELECT * FROM public.schedule_versions WHERE schedule_id=h.id ORDER BY version LOOP INSERT INTO public.work_schedule_versions(work_id,version,stages,notes,reason,created_by,created_at) VALUES(_work_id,v.version,v.stages,v.notes,v.reason,v.created_by,v.created_at); END LOOP;
IF target IS NOT NULL THEN UPDATE public.schedules SET work_id=NULL,archived=true WHERE id=target; END IF; UPDATE public.schedules SET work_id=_work_id,standalone_stages='[]',is_template=false WHERE id=h.id; UPDATE public.work_registry SET schedule_notes=h.notes,schedule_change_reason='Vínculo do cronograma avulso' WHERE id=_work_id;PERFORM set_config('jmg.schedule_batch','off',true); END $$;
REVOKE ALL ON FUNCTION public.link_schedule_work(uuid,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.link_schedule_work(uuid,uuid) TO authenticated;
COMMENT ON COLUMN public.schedules.standalone_stages IS 'Editable only while work_id is null; atomically moved into existing work_stages with stable IDs on linking. Never two editable copies.';